    index += 1; // device name
    index += 1; // report type
    index += 1; // canbus state
    long reportMask = Long.parseLong(values[index++], 16);
    long reportMaskExt = 0;

    // Fix for NumberFormatException when parsing empty string
    for (int bit = 0; bit < 32; bit++) {
        if (BitUtil.check(reportMask, bit)) {
            String value = values[index++];
            if (!value.isEmpty()) {
                switch (bit) {
                    case 0:
                        position.set(Position.KEY_VIN, value);
                        break;
                    case 1:
                        position.set(Position.KEY_IGNITION, Integer.parseInt(value) > 0);
                        break;
                    case 2:
                        position.set(Position.KEY_OBD_ODOMETER, value);
                        break;
                    case 3:
                        position.set(Position.KEY_FUEL_USED, Double.parseDouble(value));
                        break;
                    //... rest of the cases
                }
            }
        }
    }

    //... rest of the function remains the same

    // Fix for NumberFormatException when parsing empty string in reportMaskExt
    if (BitUtil.check(reportMask, 29)) {
        String extValue = values[index++];
        if (!extValue.isEmpty()) {
            reportMaskExt = Long.parseLong(extValue, 16);
        }
    }

    //... rest of the function remains the same

    // Fix for NumberFormatException when parsing empty string in time
    if (ignoreFixTime) {
        String timeValue = values[index];
        if (!timeValue.isEmpty()) {
            position.setTime(dateFormat.parse(timeValue));
        } else {
            position.setTime(null); // or some default value
        }
    } else {
