                // No change needed, existing logic already handles these correctly

                default:
                    if (idLength == 0xFE) {
                        buf.skipBytes(2); // Skip short id
                    }
                    buf.skipBytes(buf.readUnsignedByte()); // Skip unknown id's length
            }

            // Break if not enough data to read next id
            if (!buf.isReadable()) {
