    if (endIndex > 0) {
        ByteBuf frame = Unpooled.buffer();
        ByteBuf remaining = Unpooled.buffer();

        while (buf.readerIndex() < buf.writerIndex()) {
            byte b1 = buf.readByte();
            if (buf.readerIndex() < endIndex) {
                if (b1 == '}') {
