        if (parser.hasNext(4)) {
            position.set(Position.KEY_BATTERY_LEVEL, parser.nextInt());
            decodeStatus(position, parser);
        }

        int index = 0;
        String[] data = parser.next().split(",");

        index += 1; // device type

        if (BitUtil.check(mask, 0)) {
