                }
            }
        }

        return position;

    } else if (type == MSG_GPS_MODULAR) {

        while (buf.readableBytes() > 6) {
            if (buf.readableBytes() < 4) { // minimum length to read module type and length
                break;
            }
            int moduleType = buf.readUnsignedShort();
            int moduleLength = buf.readUnsignedShort();

            if (buf.readableBytes() < moduleLength) { // check for sufficient bytes to read module data
                break;
            }
            switch (moduleType) {
                case 0x03:
                    position.set(Position.KEY_ICCID, ByteBufUtil.hexDump(buf.readSlice(10)));
                    break;
                case 0x09:
                    position.set(Position.KEY_SATELLITES, buf.readUnsignedByte());
                    break;
                case 0x0a:
                    position.set(Position.KEY_SATELLITES_VISIBLE, buf.readUnsignedByte());
                    break;
                case 0x11:
                    if (buf.readableBytes() >= 10) { // check for sufficient bytes to read cell tower data
                        CellTower cellTower = CellTower.from(
                                buf.readUnsignedShort(),
                                buf.readUnsignedShort(),
                                buf.readUnsignedShort(),
                                buf.readUnsignedMedium(),
                                buf.readUnsignedByte());
                        if (cellTower.getCellId() > 0) {
                            position.setNetwork(new Network(cellTower));
                        }
                    }
                    break;
                case 0x18:
                    if (buf.readableBytes() >= 2) { // check for sufficient bytes to read battery level
                        position.set(Position.KEY_BATTERY, buf.readUnsignedShort() * 0.01);
                    }
                    break;
                case 0x28:
                    if (buf.readableBytes() >= 1) { // check for sufficient bytes to read HDOP
                        position.set(Position.KEY_HDOP, buf.readUnsignedByte() * 0.1);
                    }
                    break;
                case 0x29:
                    if (buf.readableBytes() >= 4) { // check for sufficient bytes to read index
                        position.set(Position.KEY_INDEX, buf.readUnsignedInt());
                    }
                    break;
                case 0x2a:
                    if (buf.readableBytes() >= 1) { // check for sufficient bytes to read input
                        int input = buf.readUnsignedByte();
                        position.set(Position.KEY_DOOR, BitUtil.to(input, 4) > 0);
                        position.set("tamper", BitUtil.from(input, 4) > 0);
                    }
                    break;
                case 0x2b:
                    if (buf.readableBytes() >= 1) { // check for sufficient bytes to read event
                        int event = buf.readUnsignedByte();
                        switch (event) {
                            case 0x11:
                                position.set(Position.KEY_ALARM, Position.ALARM_LOW_BATTERY);
                                break;
                            case 0x12:
                                position.set(Position.KEY_ALARM, Position.ALARM_LOW_POWER);
                                break;
                            case 0x13:
                                position.set(Position.KEY_ALARM, Position.ALARM_POWER_CUT);
                                break;
                            case 0x14:
                                position.set(Position.KEY_ALARM, Position.ALARM_REMOVING);
                                break;
                            default:
                                break;
                        }
                        position.set(Position.KEY_EVENT, event);
                    }
                    break;
                case 0x2e:
                    if (buf.readableBytes() >= 4) { // check for sufficient bytes to read odometer
                        position.set(Position.KEY_ODOMETER, buf.readUnsignedIntLE());
                    }
                    break;
                case 0x33:
                    if (buf.readableBytes() >= 15) { // check for sufficient bytes to read GPS data
                        position.setTime(new Date(buf.readUnsignedInt() * 1000));
                        position.set(Position.KEY_SATELLITES, buf.readUnsignedByte());
                        position.setAltitude(buf.readShort());

                        double latitude = buf.readUnsignedInt() / 60.0 / 30000.0;
                        double longitude = buf.readUnsignedInt() / 60.0 / 30000.0;
                        position.setSpeed(UnitsConverter.knotsFromKph(buf.readUnsignedByte()));

                        int flags = buf.readUnsignedShort();
                        position.setCourse(BitUtil.to(flags, 10));
                        position.setValid(BitUtil.check(flags, 12));

