                    break;
                case 0xA1:
                    position.set(Position.KEY_ARMED, false);
                    break;
                case 0xA2:
                case 0xA3:
                    position.set(Position.KEY_ALARM, Position.ALARM_LOW_BATTERY);
                    break;
                case 0xA4:
                    position.set(Position.KEY_ALARM, Position.ALARM_GENERAL);
